"""Shared read-only guards for the prepared ribose integration helpers."""
from pathlib import Path
from datetime import datetime, timezone
import hashlib, json, re, subprocess

if not __debug__:
    raise RuntimeError('These guarded helpers require assertions; do not use Python optimization.')

PACKAGE=Path(__file__).resolve().parent
ROOT=Path('/private/tmp/pathwaymech-next-226-20261012')
CAPTURE_ROOT=Path('/private/tmp/pathwaymech-next-225-20261012')
BUILD=Path('/private/tmp/pathwaymech-next-226-canonical-build-20261012')
IMPL=Path('/private/tmp/pathwaymech-next-226-authority-correction-20261012')
CACHE=Path('/private/tmp/pathwaymech-curation-authorities/sources')
PYTHON=Path('/private/tmp/pathwaymech-next-195-20261011/.venv/bin/python')
TARGET_REL='data/pathways/ribose-phosphorylation.yaml'
TARGET_SHA='385101d166c9150936d81bb0f1c6c0d134b6ac1e6a6454d86e238ac0576e3d71'
DOSSIER_REL='research/pathway_additions/2026-10-12-next-226'

def now():return datetime.now(timezone.utc).isoformat()
def sha(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda:stream.read(8*1024*1024),b''):h.update(block)
    return h.hexdigest()
def binding(path):
    p=Path(path);return {'path':str(p),'bytes':p.stat().st_size,'sha256':sha(p)}
def load(path):return json.loads(Path(path).read_bytes())
def verify(path,item,allow_symlink=False):
    p=Path(path)
    assert p.is_file() and (allow_symlink or not p.is_symlink()),p
    assert sha(p)==item['sha256'],p
    if 'bytes'in item:assert p.stat().st_size==item['bytes'],p
def write_new(path,value):
    with Path(path).open('x') as stream:json.dump(value,stream,indent=2,ensure_ascii=False);stream.write('\n')
def git(root,*args):return subprocess.check_output(['git',*args],cwd=root,text=True).strip()
def safe_relative(value):
    p=Path(value);assert not p.is_absolute() and '..'not in p.parts and str(p)not in ('','.');return p
def rebase(path,root):return root/Path(path).relative_to(CAPTURE_ROOT)
def inventory(root,relative):
    paths=subprocess.check_output(['rg','--files','-uu','-L',relative],cwd=root,text=True).splitlines()
    return [{'relative_path':p,**binding(root/p)} for p in sorted(paths)]
def external_new(path,root):
    p=Path(path).absolute();assert p.parent.resolve().is_relative_to(Path('/private/tmp'))
    assert p.parent.is_dir(),p.parent
    assert not p.is_relative_to(root) and not p.is_relative_to(PACKAGE)
    assert not p.exists() and not p.is_symlink(),p
def validate_base(root,base,clean=True):
    root=Path(root).absolute();assert root==ROOT and root.is_dir(),root
    assert re.fullmatch(r'[0-9a-f]{40}',base),base
    assert git(root,'rev-parse','HEAD')==base
    assert git(root,'branch','--show-current')=='feat/pathway-next-226-20261012'
    # This checks the local fetched origin/main ref, not an unperformed live GitHub query.
    subprocess.run(['git','merge-base','--is-ancestor',base,'refs/remotes/origin/main'],cwd=root,check=True)
    if clean:
        assert not git(root,'diff','--name-only') and not git(root,'diff','--cached','--name-only')
        assert set(git(root,'ls-files','--others','--exclude-standard').splitlines())<={'.venv'}
    return root
def verify_package():
    manifest=load(PACKAGE/'artifact-manifest.json')
    for item in manifest['artifacts']:verify(PACKAGE/safe_relative(item['relative_path']),item)
def verify_accepted():
    for directory,digest in [(BUILD,'aa9b5159d994cc55e36db673f0376028cc364b88accccc840bfae25f7c587566'),(Path('/private/tmp/pathwaymech-next-226-canonical-root-review-20261012'),'818eaa3a95a6048b448efc45cfab3640df062ea68d82fe79ee5121a9659b8666'),(IMPL,'2c816026bf8497e8081322f5731e357a87cb83d066454d2993e49c6c17790517'),(Path('/private/tmp/pathwaymech-next-226-authority-successor-review-20261012'),'e18c5b6908418ba6bf12df9d81bc7d7e89b3acc9ee4ed10ee96010b1a620daf6'),(Path('/private/tmp/pathwaymech-next-226-science-review-20261012'),'0d8e488bc38ca666c0fff8333a416987823c5ac9eb6242f87d906279d822275b'),(Path('/private/tmp/pathwaymech-next-226-final-predecessor-bridge-20261012'),'e54845bfc403e9d576390273bf650e475c35f34542543f6c835488c50ed58559')]:
        verify(directory/'handoff.json',{'sha256':digest})
    handoff=load(BUILD/'handoff.json')
    for item in handoff.values():
        if isinstance(item,dict) and {'path','sha256'}<=set(item):verify(item['path'],item)
    assert sha(BUILD/'corpus/ribose-phosphorylation.yaml')==TARGET_SHA
def verify_captured226(root):
    capture=load(BUILD/'baseline-capture.json')
    actual={r['relative_path'] for r in inventory(root,'data/pathways')}
    expected={str(Path(item['path']).relative_to(CAPTURE_ROOT)) for item in capture['records']}
    assert actual==expected,'Captured226 record file set mismatch (ignored/hidden included)'
    for item in capture['records']+capture['authority_bindings']+capture['code_inputs']+[capture['ontology_builder']]:verify(rebase(item['path'],root),item)
    assert len([p for p in expected if p.endswith('.yaml')])==226
    assert sha(root/'data/pathways/l-threonine-degradation-iii.yaml')=='5e003a44a1519e0a121a39819b334e57feee397e033d6db2ccec01399898daa7'
    for item in load(BUILD/'code-change-bindings.json')['changes']:
        p=root/item['relative_path']
        if item['baseline'] is None:assert not p.exists() and not p.is_symlink(),p
        else:verify(p,item['baseline'])
    return capture
def verify_adopted(root):
    assert sha(root/TARGET_REL)==TARGET_SHA
    for key,relative in [('source_snapshot','data/identifier_authorities/sources.json'),('ontology_snapshot','data/identifier_authorities/ontology.json'),('manifest','conf/identifier_sources.json'),('rhea_updates','conf/rhea_identifier_updates.json')]:verify(root/relative,load(BUILD/'handoff.json')[key])
    for item in load(BUILD/'code-change-bindings.json')['changes']:verify(root/item['relative_path'],item['candidate'])
